"""sklearn.conftest — pytest configuration for the sklearn test suite.

The shim doesn't run sklearn's tests so most fixtures are stubbed.
When pytest isn't available we expose no-op decorators in its place."""


try:
    import pytest
except ImportError:
    class _PytestStub:
        """No-op pytest replacement used when pytest isn't installed."""
        @staticmethod
        def fixture(*args, **kwargs):
            def _dec(fn): return fn
            return _dec(args[0]) if args and callable(args[0]) else _dec

        class _MarkStub:
            def __getattr__(self, name):
                def _wrap(*a, **kw):
                    def _dec(fn): return fn
                    return _dec(a[0]) if a and callable(a[0]) else _dec
                return _wrap
        mark = _MarkStub()

        @staticmethod
        def skipif(*args, **kwargs):
            def _dec(fn): return fn
            return _dec
    pytest = _PytestStub()


def pytest_collection_modifyitems(config, items):
    """Pytest hook — no-op."""
    pass


def pytest_configure(config):
    """Pytest hook — register custom markers."""
    pass


def pytest_unconfigure(config):
    """Pytest hook — cleanup."""
    pass


